<section class="content-width admin-layout"><form class="admin-create" action="/admin/staff/save" method="post" data-submit-label="Menyimpan…"><input type="hidden" name="_token" value="<?= e($csrfToken) ?>"><h2>Tambah Petugas</h2><label>Nama<input name="name" maxlength="100" required></label><label>Email<input name="email" type="email" maxlength="190" required></label><label>Telepon<input name="phone" maxlength="20"></label><label>Password<input name="password" type="password" minlength="8" maxlength="72" required></label><button class="btn btn-primary" type="submit">Buat akun</button></form><div class="admin-list"><?php foreach ($staff as $person): ?><article><form action="/admin/staff/save" method="post"><input type="hidden" name="_token" value="<?= e($csrfToken) ?>"><input type="hidden" name="id" value="<?= (int) $person['id'] ?>"><label>Nama<input name="name" value="<?= e($person['name']) ?>" required></label><label>Email<input name="email" type="email" value="<?= e($person['email']) ?>" required></label><label>Telepon<input name="phone" value="<?= e($person['phone']) ?>"></label><label>Password baru (opsional)<input name="password" type="password" minlength="8" maxlength="72"></label><span><?= (int) $person['is_active'] === 1 ? 'Aktif' : 'Nonaktif' ?></span><button class="btn btn-light" type="submit">Simpan</button></form><form action="/admin/staff/toggle" method="post"><input type="hidden" name="_token" value="<?= e($csrfToken) ?>"><input type="hidden" name="id" value="<?= (int) $person['id'] ?>"><button class="admin-toggle" type="submit"><?= (int) $person['is_active'] === 1 ? 'Nonaktifkan' : 'Aktifkan' ?></button></form></article><?php endforeach; ?></div></section>
